"use client";

import { useState, useEffect } from "react";
import Header from "@/components/common/Header";
import Navbar from "@/components/common/Navbar";
import UserSidebar from "@/components/common/UserSidebar";
import Footer from "@/components/common/Footer";
import axios from "axios";
import UserProfileForm from "@/components/user/UserProfileForm";

const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL;

const UserProfilePage = () => {
  const [user, setUser] = useState({
    id: null,
    fullname: "",
    email: "",
    photoProfileUrl: null,
    birthDate: "",
    gender: "",
    isVerified: false,
  });

  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchUserProfile();
  }, []);

  const fetchUserProfile = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("accessToken"); 
      if (!token) {
        console.error("User not authenticated");
        setLoading(false);
        return;
      }
      
      const response = await axios.get(`${BACKEND_URL}/api/v1/user/profile`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      
      const userData = response.data.data;
      
      const formattedUser = {
        id: userData.id,
        fullname: userData.fullname,
        email: userData.email,
        photoProfileUrl: userData.photoProfileUrl || "/default-avatar.png",
        birthDate: userData.birthDate ? userData.birthDate.split("T")[0] : "",
        gender: userData.gender,
        isVerified: userData.isVerified,
      };
  
      setUser(formattedUser);
    } catch (error) {
      console.error("Error fetching user profile:", error);
    } finally {
      setLoading(false);
    }
  };
  
  return (
    <>
      <Header />
      <Navbar />
      <div className="flex text-black">
        <UserSidebar />
        <div className="container mx-auto p-6 text-black">
          <h1 className="text-2xl font-bold mb-4">User Profile</h1>

          {loading ? (
            <p className="text-center text-gray-500">Loading...</p>
          ) : (
            <>
              <UserProfileForm user={user} setUser={setUser} fetchUserProfile={fetchUserProfile} />
            </>
          )}
        </div>
      </div>
      <Footer />
    </>
  );
};

export default UserProfilePage;
